from decimal import Decimal, ROUND_HALF_UP


def tax(amount, rate):
    """Tax on an invoice amount, rounded half up to the cent (FIN-12)."""
    tax_amount = Decimal(str(amount)) * Decimal(str(rate))
    return float(tax_amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

from src.invoice import tax


def test_invoice_tax():
    # Finance policy FIN-12: tax is rounded half up to the cent.
    assert tax(112.50, 0.09) == 10.13


def test_invoice_tax_rounding_boundaries():
    assert tax(100.04, 0.1) == 10.00
    assert tax(100.05, 0.1) == 10.01
    assert tax(100.06, 0.1) == 10.01


def test_invoice_tax_exact_cent():
    assert tax(100, 0.09) == 9.00


def test_invoice_tax_zero():
    assert tax(0, 0.09) == 0.00

